    // ============================================================
    // V3.7：捕获 AutoTable 自己的查询请求认证信息与 records/query 返回值
    // 目的：批量进展直接复用“正常单条修改”实际使用的 PATCH /records/{id}
    // 不再依赖脚本模拟双击 / 失焦。
    // ============================================================

    function headersToPlainObject(headersLike) {
        const out = {};

        try {
            if (!headersLike) return out;

            if (headersLike instanceof Headers) {
                headersLike.forEach((value, key) => {
                    out[String(key).toLowerCase()] = String(value);
                });
                return out;
            }

            if (Array.isArray(headersLike)) {
                for (const pair of headersLike) {
                    if (!Array.isArray(pair) || pair.length < 2) continue;
                    out[String(pair[0]).toLowerCase()] = String(pair[1]);
                }
                return out;
            }

            for (const [key, value] of Object.entries(headersLike)) {
                out[String(key).toLowerCase()] = String(value);
            }
        } catch (err) {
            console.warn('[AutoTable 工具集] 读取请求头失败：', err);
        }

        return out;
    }

    function captureUsefulApiHeaders(headersLike) {
        const all = headersToPlainObject(headersLike);
        const next = { ...state.apiCapture.headers };

        // 只缓存正常保存真正需要的认证/工作区信息。
        for (const key of ['authorization', 'x-workspace-id']) {
            if (all[key]) next[key] = all[key];
        }

        state.apiCapture.headers = next;
        state.apiCapture.ready = Boolean(
            next.authorization || next['x-workspace-id']
        );
    }

    function rememberQueryItems(data) {
        const items = Array.isArray(data?.items) ? data.items : [];

        for (const item of items) {
            if (!item?.id) continue;
            state.apiCapture.recordsById.set(item.id, item);
        }
    }

    function installAutoTableFetchCapture() {
        const pageWindow = typeof unsafeWindow !== 'undefined'
            ? unsafeWindow
            : window;

        if (!pageWindow?.fetch) return;
        if (pageWindow.fetch.__attV37Wrapped) return;

        const originalFetch = pageWindow.fetch;

        async function wrappedFetch(input, init = {}) {
            let url = '';
            let method = 'GET';
            let headersLike = null;
            let bodyText = null;

            try {
                url = typeof input === 'string'
                    ? input
                    : (input?.url || '');

                method = String(
                    init?.method ||
                    input?.method ||
                    'GET'
                ).toUpperCase();

                headersLike = init?.headers || input?.headers || null;
                captureUsefulApiHeaders(headersLike);

                if (typeof init?.body === 'string') {
                    bodyText = init.body;
                }
            } catch (err) {
                console.warn('[AutoTable 工具集] 捕获 fetch 请求信息失败：', err);
            }

            const response = await originalFetch.apply(this, arguments);

            try {
                const absolute = new URL(url, location.href);

                // AutoTable 切换主题时实际调用：
                // PATCH /auth/me/theme  body: {"themeMode":"dark|light"}
                const isThemeChange =
                    method === 'PATCH' &&
                    /\/auth\/me\/theme$/i.test(absolute.pathname);

                if (isThemeChange) {
                    let requestedMode = 'unknown';

                    if (bodyText) {
                        try {
                            requestedMode = normalizeThemeMode(
                                JSON.parse(bodyText)?.themeMode
                            );
                        } catch {}
                    }

                    if (response.ok) {
                        response.clone().json().then(data => {
                            const mode =
                                normalizeThemeMode(data?.themeMode) !== 'unknown'
                                    ? normalizeThemeMode(data?.themeMode)
                                    : requestedMode;

                            if (mode !== 'unknown') {
                                applyNativeThemeMode(mode, '主题接口');
                            }
                        }).catch(() => {
                            if (requestedMode !== 'unknown') {
                                applyNativeThemeMode(requestedMode, '主题接口');
                            }
                        });
                    }
                }

                const isQuery =
                    method === 'POST' &&
                    /\/tables\/[^/]+\/records\/query$/i.test(absolute.pathname);

                if (isQuery) {
                    let body = null;

                    if (bodyText) {
                        try {
                            body = JSON.parse(bodyText);
                        } catch {}
                    }

                    state.apiCapture.latestQuery = {
                        url: absolute.pathname + absolute.search,
                        body
                    };

                    response.clone().json().then(data => {
                        rememberQueryItems(data);
                    }).catch(() => {});
                }
            } catch {}

            return response;
        }

        try {
            Object.defineProperty(wrappedFetch, '__attV37Wrapped', {
                value: true
            });
        } catch {
            wrappedFetch.__attV37Wrapped = true;
        }

        pageWindow.fetch = wrappedFetch;
        state.apiCapture.originalFetch = originalFetch;
    }

    installAutoTableFetchCapture();

    function normalizeComboList(value) {
        const source = Array.isArray(value) ? value : DEFAULTS.combos;

        return source.map((raw, index) => {
            const combo = raw && typeof raw === 'object' ? raw : {};
            const fields = Array.isArray(combo.fields)
                ? combo.fields.map(v => sanitizeText(v)).filter(Boolean)
                : [];

            const tableBindings = {};
            if (combo.tableBindings && typeof combo.tableBindings === 'object' && !Array.isArray(combo.tableBindings)) {
                for (const [key, bindingRaw] of Object.entries(combo.tableBindings)) {
                    if (!bindingRaw || typeof bindingRaw !== 'object') continue;

                    const bindingFields = Array.isArray(bindingRaw.fields)
                        ? bindingRaw.fields.map(item => {
                            if (typeof item === 'string') {
                                const name = sanitizeText(item);
                                return name ? { fieldId: '', name, label: name } : null;
                            }

                            if (!item || typeof item !== 'object') return null;
                            const fieldId = String(item.fieldId || '');
                            const name = sanitizeText(item.name || item.label || '');
                            const label = sanitizeText(item.label || item.name || '');
                            if (!fieldId && !name) return null;
                            return { fieldId, name, label: label || name };
                        }).filter(Boolean)
                        : [];

                    tableBindings[key] = {
                        tableId: String(bindingRaw.tableId || ''),
                        tableName: sanitizeText(bindingRaw.tableName || ''),
                        fields: bindingFields,
                        updatedAt: Number(bindingRaw.updatedAt || 0)
                    };
                }
            }

            return {
                id: String(combo.id || `combo_${Date.now()}_${index}`),
                name: sanitizeText(combo.name || `字段组合 ${index + 1}`),
                fields,
                format: ['pipe', 'space', 'tab', 'custom', 'lines'].includes(combo.format) ? combo.format : 'pipe',
                customDelimiter: String(combo.customDelimiter ?? ''),
                hotkey: String(combo.hotkey || ''),
                tableBindings
            };
        });
    }

