/* ============================================================================
 * AutoTable 表格关联复制按钮隐藏 V6.5
 * --------------------------------------------------------------------------
 * 追加式独立模块：不修改上方任何原有代码。
 *
 * 功能：
 * 1) 在“设置”页增加“隐藏表格关联复制按钮”开关；
 * 2) 开启后仅隐藏 .cell-relation-copy 按钮；
 * 3) 不删除 DOM、不拦截单元格事件，不影响关联文本、关系图标、编辑、聚焦、列置顶；
 * 4) CSS 级隐藏天然兼容 React 重绘、虚拟滚动和新加载行；
 * 5) 设置持久化保存，默认开启。
 * ========================================================================== */
(function () {
    'use strict';

    const MOD = {
        version: 'V6.5',
        styleId: 'att-hide-relation-copy-style-v65',
        hostId: 'att-table-copy-settings-host-v65',
        cardId: 'att-table-copy-settings-card-v65',
        storageKey: 'att_hide_relation_copy_buttons_v65',
        toolboxId: 'att-toolbox-root',
        contentSelector: '.att-content',
        settingsTabSelector: '.att-tab[data-tab="settings"]',
        buttonSelector: '.cell-relation-copy'
    };

    const state = {
        enabled: loadEnabled(),
        observer: null,
        timer: 0
    };

    function loadEnabled() {
        try {
            if (typeof GM_getValue === 'function') {
                return Boolean(GM_getValue(MOD.storageKey, true));
            }
        } catch (_) {}
        try {
            const raw = localStorage.getItem(MOD.storageKey);
            return raw == null ? true : raw === '1';
        } catch (_) {}
        return true;
    }

    function saveEnabled(value) {
        try {
            if (typeof GM_setValue === 'function') {
                GM_setValue(MOD.storageKey, Boolean(value));
                return;
            }
        } catch (_) {}
        try { localStorage.setItem(MOD.storageKey, value ? '1' : '0'); } catch (_) {}
    }

    function addStyles() {
        if (document.getElementById(MOD.styleId)) return;
        const style = document.createElement('style');
        style.id = MOD.styleId;
        style.textContent = `
            body.att-hide-relation-copy-v65 ${MOD.buttonSelector} {
                display: none !important;
            }

            #${MOD.hostId} {
                display: none;
                margin: 9px 0 0;
                padding: 0;
            }

            #${MOD.toolboxId}:has(${MOD.settingsTabSelector}.att-active)
            ${MOD.contentSelector} > #${MOD.hostId} {
                display: block;
            }

            #${MOD.cardId} {
                margin: 0 !important;
            }
        `;
        document.documentElement.appendChild(style);
    }

    function applyState() {
        document.body?.classList.toggle('att-hide-relation-copy-v65', Boolean(state.enabled));
        const checkbox = document.querySelector(`#${MOD.cardId} input[data-att-hide-relation-copy]`);
        if (checkbox instanceof HTMLInputElement) checkbox.checked = Boolean(state.enabled);
        const status = document.querySelector(`#${MOD.cardId} .att-table-copy-status-v65`);
        if (status) {
            status.textContent = state.enabled
                ? '已隐藏：表格关联字段右侧的复制按钮不会显示。'
                : '已显示：恢复 AutoTable 原生关联复制按钮。';
        }
    }

    function getToolbox() {
        return document.getElementById(MOD.toolboxId);
    }

    function ensureHost() {
        const toolbox = getToolbox();
        const content = toolbox?.querySelector(MOD.contentSelector);
        if (!toolbox || !(content instanceof HTMLElement)) return null;

        let host = document.getElementById(MOD.hostId);
        if (!(host instanceof HTMLElement) || host.parentElement !== content) {
            host?.remove();
            host = document.createElement('div');
            host.id = MOD.hostId;
            host.setAttribute('data-att-table-copy-settings-host', '1');
            content.appendChild(host);
        }
        return host;
    }

    function buildCard() {
        const card = document.createElement('div');
        card.id = MOD.cardId;
        card.className = 'att-card';
        card.innerHTML = `
            <div class="att-row">
                <div style="min-width:0;">
                    <div class="att-card-title">隐藏表格关联复制按钮</div>
                    <div class="att-card-desc">
                        隐藏关联字段右侧 AutoTable 原生的“小复制”按钮，仅影响
                        <code>.cell-relation-copy</code> 的显示，不影响单元格内容、编辑、关联图标或工具集复制功能。
                    </div>
                </div>
                <label class="att-switch" title="隐藏表格关联复制按钮">
                    <input type="checkbox" data-att-hide-relation-copy ${state.enabled ? 'checked' : ''}>
                    <span class="att-slider"></span>
                </label>
            </div>
            <div class="att-sub-label att-table-copy-status-v65" style="margin-top:8px;">
                ${state.enabled
                    ? '已隐藏：表格关联字段右侧的复制按钮不会显示。'
                    : '已显示：恢复 AutoTable 原生关联复制按钮。'}
            </div>
        `;
        return card;
    }

    function ensureCard() {
        const host = ensureHost();
        if (!host) return null;

        let card = document.getElementById(MOD.cardId);
        if (!(card instanceof HTMLElement)) {
            card = buildCard();
            host.appendChild(card);
        } else if (card.parentElement !== host) {
            host.appendChild(card);
        }
        applyState();
        return card;
    }

    function sync() {
        clearTimeout(state.timer);
        state.timer = 0;
        addStyles();
        ensureCard();
        applyState();
    }

    function scheduleSync(delay = 50) {
        clearTimeout(state.timer);
        state.timer = window.setTimeout(sync, Math.max(0, delay));
    }

    function bindEvents() {
        if (document.documentElement.dataset.attHideRelationCopyV65Bound === '1') return;
        document.documentElement.dataset.attHideRelationCopyV65Bound = '1';

        document.addEventListener('change', event => {
            const target = event.target;
            if (!(target instanceof HTMLInputElement)) return;
            if (!target.hasAttribute('data-att-hide-relation-copy')) return;

            state.enabled = target.checked;
            saveEnabled(state.enabled);
            applyState();
        }, true);
    }

    function init() {
        addStyles();
        bindEvents();
        sync();

        state.observer = new MutationObserver(records => {
            const relevant = records.some(record => {
                const target = record.target;
                if (target instanceof Element && target.closest?.(`#${MOD.hostId}`)) return false;
                return Array.from(record.addedNodes || []).some(node =>
                    node instanceof Element && (
                        node.id === MOD.toolboxId ||
                        node.querySelector?.(`#${MOD.toolboxId}`) ||
                        node.matches?.('.att-content,.att-tab,[data-section="settings"]') ||
                        node.querySelector?.('.att-content,.att-tab,[data-section="settings"]')
                    )
                );
            });
            if (relevant) scheduleSync(70);
        });

        state.observer.observe(document.documentElement, {
            childList: true,
            subtree: true
        });

        console.log('[AutoTable 工具集 V6.5] 已加载：隐藏表格关联复制按钮 / 设置页开关 / CSS 级虚拟滚动兼容');
    }

    if (document.body) init();
    else window.addEventListener('DOMContentLoaded', init, { once: true });
})();


/* ============================================================================
 * AutoTable 隐藏关联复制按钮 · 占位释放修复 V6.5.1
 * --------------------------------------------------------------------------
 * 追加式独立补丁：不修改 V6.5 及其之前任何代码。
 *
 * 修复：
 * - V6.5 隐藏 .cell-relation-copy 后，AutoTable 原生 shell 仍可能为按钮保留宽度；
 * - 仅在“隐藏表格关联复制按钮”开启时，释放 shell / relation 的 gap、宽度和右侧预留；
 * - 关闭开关后本补丁完全不生效，恢复 AutoTable 原生布局。
 * ========================================================================== */
(function () {
    'use strict';

    const STYLE_ID = 'att-hide-relation-copy-release-space-v651';
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement('style');
    style.id = STYLE_ID;
    style.textContent = `
        /* 隐藏按钮后，让关系字段内容真正占满整个单元格可用宽度。 */
        body.att-hide-relation-copy-v65 .grid-cell .cell-relation-copy-shell {
            width: 100% !important;
            max-width: 100% !important;
            min-width: 0 !important;
            box-sizing: border-box !important;
            gap: 0 !important;
            column-gap: 0 !important;
            justify-content: flex-start !important;
            grid-template-columns: minmax(0, 1fr) !important;
            padding-right: 0 !important;
            margin-right: 0 !important;
        }

        /* AutoTable 常见实现会给左侧 relation 本身预留复制按钮宽度。 */
        body.att-hide-relation-copy-v65 .grid-cell .cell-relation-copy-shell > .cell-relation,
        body.att-hide-relation-copy-v65 .grid-cell .cell-relation-copy-shell > .cell-text.cell-relation {
            flex: 1 1 auto !important;
            width: 100% !important;
            max-width: 100% !important;
            min-width: 0 !important;
            box-sizing: border-box !important;
            padding-right: 0 !important;
            margin-right: 0 !important;
        }

        /* 标签仍允许正常省略，但可使用全部剩余宽度。 */
        body.att-hide-relation-copy-v65 .grid-cell .cell-relation-copy-shell .cell-relation-label {
            flex: 1 1 auto !important;
            min-width: 0 !important;
            max-width: 100% !important;
        }

        /* 双保险：避免按钮自身的 margin / flex-basis 继续占位。 */
        body.att-hide-relation-copy-v65 .grid-cell .cell-relation-copy-shell > .cell-relation-copy {
            display: none !important;
            flex: 0 0 0 !important;
            width: 0 !important;
            min-width: 0 !important;
            max-width: 0 !important;
            padding: 0 !important;
            margin: 0 !important;
            border: 0 !important;
        }
    `;

    document.documentElement.appendChild(style);
    console.log('[AutoTable 工具集 V6.5.1] 已加载：隐藏关联复制按钮后释放文字区域占位');
})();


