    function sync(root, fieldId, options = {}) {
        if (!(root instanceof Element) || !root.isConnected || !fieldId) return;
        if (activeRoot && activeRoot !== root) activeRoot.removeAttribute(FIX.rootAttr);
        activeRoot = root;
        activeFieldId = String(fieldId);
        activeOptions = {
            rowEnabled:Boolean(options.rowEnabled),
            columnEnabled:Boolean(options.columnEnabled)
        };
        root.setAttribute(FIX.rootAttr, '1');
        ensureLiveStyle().textContent = activeOptions.columnEnabled ? buildLiveCss(activeFieldId) : '';
    }

    function recoverFromCurrentDom() {
        const focus = document.querySelector('.grid-root .grid-cell.att-focus-cell[data-grid-field-id]');
        if (!focus) return;
        const root = focus.closest('.grid-root');
        const fieldId = focus.getAttribute('data-grid-field-id') || '';
        if (!root || !fieldId) return;
        const row = focus.closest('.grid-row');
        sync(root, fieldId, {
            rowEnabled:Boolean(row?.classList.contains('att-focus-row')),
            columnEnabled:Boolean(root.querySelector('.att-focus-column'))
        });
    }

